// Custom firmware (CFW, CC3200 and ESP32 boxes): calls of the teddyCloud /api/cfw/... endpoints.
// Written by hand, not generated by the OpenAPI generator like src/api/apis and src/api/models:
// the /api/cfw endpoints are not part of api/swagger.yaml.

import { TeddyCloudApi } from "./apis/TeddyCloudApi";
import { defaultAPIConfig } from "../config/defaultApiConfig";
import { ResponseError } from "./runtime";

const api = new TeddyCloudApi(defaultAPIConfig());

export const CFW_CAP = {
    resume: 1 << 0,
    shuffle: 1 << 1,
    sleepTimer: 1 << 2,
    eventTags: 1 << 3,
    restartGesture: 1 << 4,
    limitsPerFigure: 1 << 5,
    globalSettings: 1 << 6,
    foreignTags: 1 << 7,
    locks: 1 << 8,
    eventTagExt: 1 << 9,
    remote: 1 << 10,
    battery: 1 << 11,
};

/** the last battery report of the box */
export interface CfwBattery {
    mv: number;
    station: boolean;
    low: boolean;
    critical: boolean;
    implausible: boolean;
    /** 0 at the hello, 1 a scheduled measurement, 2 lifted off the station */
    reason: number;
    time: number;
    /** charge from the voltage, 0-100; missing on the charger */
    percent?: number;
    /** playing time left at the volume of the report, once the box's capacity is learned */
    remainingMin?: number;
    learned?: boolean;
}

export type CfwChannel = "none" | "release" | "beta" | "alpha";

/** box generation of an image or a box; servers without the ESP32 support report none (cc3200) */
export type CfwPlatform = "cc3200" | "esp32";

export interface CfwBox {
    id: string;
    commonName: string;
    boxName: string;
    isCfw: boolean;
    platform?: CfwPlatform;
    /** build delivered to the original firmware of an ESP32 box (first installation), 0: none */
    esp32Delivered?: number;
    /** the value of its setup page the box reported last for item 7, 0: none yet */
    pageVersion?: number;
    version: number;
    capabilities: number;
    updateResult: number;
    rolledBackBuild: number;
    helloTime: number;
    helloValid: boolean;
    online: boolean;
    lastOfferedBuild: number;
    lastOfferTime: number;
    /** cfw.show_battery of the box; servers without the battery report send none */
    showBattery?: boolean;
    battery?: CfwBattery;
    settings: { enabled: boolean; settingsSync: boolean; remoteControl: boolean };
    update: {
        enabled: boolean;
        channel: CfwChannel;
        mode: "manual" | "automatic";
        target: number;
        allowRolledBack: boolean;
        next: number;
    };
}

/** CFW support is on for the box (cfw.enabled, with its overlay) */
export const cfwEnabledFor = (box?: CfwBox) => Boolean(box?.settings?.enabled);

/** the box can be remote-controlled: CFW with the remote capability, and allowed for the box */
export const cfwRemoteAvailable = (box?: CfwBox) =>
    Boolean(
        box?.isCfw &&
        cfwEnabledFor(box) &&
        box.settings.remoteControl &&
        box.capabilities & CFW_CAP.remote,
    );

/** null: not set (the box behaves as without the setting) */
export interface CfwProfile {
    resume: boolean | null;
    shuffle: boolean | null;
    sleepMinutes: number | null;
    speakerLimit: number | null;
    headphoneLimit: number | null;
    ledLevel: number | null;
    slapLock: boolean | null;
    tiltLock: boolean | null;
    volumeLock: boolean | null;
}

export interface CfwAction {
    action: number;
    mode: number;
    value: number;
}

export interface CfwEvent {
    tones: boolean;
    actions: CfwAction[];
}

export interface CfwTag {
    ruid: string;
    kind: "none" | "profile" | "event";
    origin?: "box" | "server" | "tool" | "unknown";
    timestamp?: number;
    profile?: CfwProfile;
    event?: CfwEvent;
}

export interface CfwStatus {
    helloValid?: boolean;
    online?: boolean;
    capabilities?: number;
    remote?: boolean;
    queued?: number;
    status?: {
        state: "idle" | "idleWithFigure" | "playing" | "paused" | "preparing" | "unknown";
        ruid: string;
        audioId: number;
        chapter: number;
        position: number;
        volume: number;
        limit: number;
        headphones: boolean;
        batteryMv: number;
        charging: boolean;
        locks: { slap: boolean; tilt: boolean; volume: boolean };
        time: number;
    };
    lastResult?: { command: number; result: number; time: number };
    lastLockedGesture?: { gesture: number; source: string; time: number };
}

export interface CfwImage {
    build: number;
    version: string;
    revision: string;
    buildDate: string;
    channel: CfwChannel;
    source: string;
    githubTag: string;
    notes: string;
    added: number;
    size: number;
    platform?: CfwPlatform;
    /** the original firmware of the ESP32 box, for the return */
    original?: boolean;
    /** what teddyCloud patched in an original image */
    patches?: string;
    /** the setup page that came with the image in its release package, 0: none */
    page?: number;
    /** the page differs from the one of the next older image of the platform */
    pageNew?: boolean;
    /** the page's version: its cfw-page-version meta, else the image's version */
    pageLabel?: string;
    /** the firmware the page needs at least (its cfw-page-requires), "" when it names none */
    pageRequires?: string;
    /** the release package is kept with this CC3200 image (preloader, card tree) */
    package?: boolean;
}

/** teddyCloud's patches of an original ESP32 image on upload; empty or 0: none */
export interface CfwEsp32Patch {
    hostname?: string;
    hostnameOld?: string;
    port?: number;
}

export interface CfwGithubRelease {
    tag: string;
    name: string;
    published: string;
    channel: CfwChannel;
    hasImage: boolean;
    downloaded: boolean;
}

/** a setup page: its value for item 7 (0: none) and version */
export interface CfwPage {
    page: number;
    label: string;
    /** the firmware the page needs at least (its cfw-page-requires), "" when it names none */
    requires?: string;
}

export interface CfwFirmwareResponse {
    images: CfwImage[];
    /** the page for images without one of their own */
    defaultPage?: CfwPage;
    github: {
        repo: string;
        autoDownload: number;
        lastCheck: number;
        message: string;
        releases: CfwGithubRelease[];
    };
}

export interface CfwResult {
    ok: boolean;
    message: string;
}

/** throws an Error with the server's message on an error answer */
async function getJson<T>(path: string): Promise<T> {
    try {
        const response = await api.apiGetTeddyCloudApiRaw(path);
        return (await response.json()) as T;
    } catch (error) {
        if (error instanceof ResponseError) {
            const answer = await error.response.json().catch(() => undefined);
            throw new Error(answer?.message ?? error.response.statusText);
        }
        throw error;
    }
}

/** never throws: network errors come back as { ok: false } as well */
async function result(request: () => Promise<Response>): Promise<CfwResult> {
    try {
        const response = await request();
        return await response
            .json()
            .catch(() => ({ ok: response.ok, message: response.statusText }));
    } catch (error) {
        return { ok: false, message: String(error) };
    }
}

const postJson = (path: string, body: unknown) =>
    result(() =>
        api.apiPostTeddyCloudRaw(path, JSON.stringify(body), undefined, undefined, {
            "Content-Type": "application/json",
        }),
    );

const enc = encodeURIComponent;

export const cfwApi = {
    boxes: () => getJson<{ boxes: CfwBox[] }>("/api/cfw/boxes").then((r) => r.boxes),
    tag: (ruid: string) => getJson<CfwTag>(`/api/cfw/tag?ruid=${enc(ruid)}`),
    setTag: (ruid: string, tag: Omit<CfwTag, "ruid">) =>
        postJson(`/api/cfw/tag?ruid=${enc(ruid)}`, tag),
    remote: (boxId: string, command: string, extra: Record<string, unknown> = {}) =>
        postJson(`/api/cfw/remote?overlay=${enc(boxId)}`, { command, ...extra }),
    status: (boxId: string) => getJson<CfwStatus>(`/api/cfw/status?overlay=${enc(boxId)}`),
    firmware: () => getJson<CfwFirmwareResponse>("/api/cfw/firmware"),
    uploadFirmware: (file: File, channel: CfwChannel, patch: CfwEsp32Patch = {}) => {
        const formData = new FormData();
        formData.append("file", file, file.name);
        let query = `channel=${enc(channel)}`;
        if (patch.hostname) query += `&hostname=${enc(patch.hostname)}`;
        if (patch.hostname && patch.hostnameOld) query += `&hostname_old=${enc(patch.hostnameOld)}`;
        if (patch.port) query += `&port=${patch.port}`;
        return result(() =>
            api.apiPostTeddyCloudFormDataRaw(`/api/cfw/firmware/upload?${query}`, formData),
        ) as Promise<CfwResult & { image?: CfwImage; images?: CfwImage[] }>;
    },
    /** a setup page alone: for the image (build and platform), or without one as the default page */
    uploadPage: (file: File, image?: CfwImage) => {
        const formData = new FormData();
        formData.append("file", file, file.name);
        const query = image
            ? `build=${image.build}&platform=${enc(image.platform ?? "cc3200")}`
            : "";
        return result(() =>
            api.apiPostTeddyCloudFormDataRaw(`/api/cfw/firmware/upload?${query}`, formData),
        ) as Promise<CfwResult & { page?: CfwPage }>;
    },
    editFirmware: (image: CfwImage, change: { channel?: CfwChannel; notes?: string }) =>
        postJson("/api/cfw/firmware/edit", {
            build: image.build,
            platform: image.platform ?? "cc3200",
            ...change,
        }),
    deleteFirmware: (image: CfwImage) =>
        postJson("/api/cfw/firmware/delete", {
            build: image.build,
            platform: image.platform ?? "cc3200",
        }),
    checkGithub: () => postJson("/api/cfw/firmware/github", {}),
    downloadGithub: (tag: string) => postJson("/api/cfw/firmware/githubDownload", { tag }),
    deliver: (boxId: string, build: number, now: boolean) =>
        postJson(`/api/cfw/deliver?overlay=${enc(boxId)}`, { build, now }),
    /** the name or address under which the boxes reach this server (Host header of the last box request; empty if none yet) */
    boxHost: () => getJson<{ host: string; apiPort: number }>("/api/cfw/boxHost"),
    /** the release package kept with a CC3200 image, for setting up a box in the browser */
    package: async (build: number): Promise<Uint8Array> => {
        const response = await api.apiGetTeddyCloudApiRaw(
            `/api/cfw/firmware/package?build=${build}`,
        );
        return new Uint8Array(await response.arrayBuffer());
    },
    /** this teddyCloud's CA as the replacement the box checks the server with (c2.der) */
    caReplacement: async (): Promise<Uint8Array> => {
        const response = await api.apiGetTeddyCloudApiRaw("/api/getFile/c2.der");
        return new Uint8Array(await response.arrayBuffer());
    },
    /** the certificates of a box teddyCloud does not know yet, under its MAC (and as the defaults where there are none) */
    uploadCertsByMac: async (mac: string, files: { name: string; data: Uint8Array }[]) => {
        const formData = new FormData();
        for (const f of files) formData.append("filename", new Blob([f.data as BlobPart]), f.name);
        await api.apiPostTeddyCloudFormDataRaw(`/api/uploadCert?mac=${enc(mac)}`, formData);
    },
    /** the box checks for an update at once; the assignment stays as it is */
    checkNow: (boxId: string) => postJson(`/api/cfw/deliver?overlay=${enc(boxId)}`, { now: true }),
    /** a setting, of the box when boxId is given, written to the config at once */
    setSetting: async (
        name: string,
        value: string | number | boolean,
        boxId?: string,
    ): Promise<CfwResult> => {
        try {
            await api.apiPostTeddyCloudSetting(name, value, boxId);
            await api.apiTriggerWriteConfigGet();
            return { ok: true, message: "OK" };
        } catch (error) {
            return { ok: false, message: String(error) };
        }
    },
};

/** "YYYY-MM-DD HH:MM" of a build number (seconds since 1970) in the browser's local time */
export function formatBuild(build: number): string {
    if (!build) return "-";
    const d = new Date(build * 1000);
    const two = (n: number) => String(n).padStart(2, "0");
    return `${d.getFullYear()}-${two(d.getMonth() + 1)}-${two(d.getDate())} ${two(d.getHours())}:${two(d.getMinutes())}`;
}

export function formatTime(seconds?: number): string {
    if (!seconds) return "-";
    return new Date(seconds * 1000).toLocaleString();
}
